//! Tests against independently produced dfVFS fixtures, never generated by this
//! parser. Expected raw bytes are the upstream raw image, gzip-wrapped locally.

use inodex::{
    ewf::{EwfImage, hex},
    image::DiskImage,
};
use std::{
    fs,
    io::{Read, Seek, SeekFrom},
    path::PathBuf,
};

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn expected() -> Vec<u8> {
    let mut bytes = Vec::new();
    flate2::read::GzDecoder::new(&include_bytes!("fixtures/ext2.raw.gz")[..])
        .read_to_end(&mut bytes)
        .unwrap();
    bytes
}

#[test]
fn compressed_image_matches_every_raw_byte_and_acquisition_hash() {
    let mut image = EwfImage::open(fixture("ext2.E01")).unwrap();
    assert_eq!(image.len(), 4_194_304);
    assert_eq!(image.sector_size(), 512);
    assert_eq!(image.metadata().chunk_count, 128);
    assert_eq!(image.metadata().chunk_size(), 32768);
    assert_eq!(image.metadata().acquisition["c"], "case");
    assert_eq!(image.metadata().acquisition["e"], "examiner");
    // The header2 timestamp is a Unix timestamp; header has a legacy date.
    assert_eq!(image.metadata().acquisition["m"], "1626967998");
    let mut decoded = Vec::new();
    image.read_to_end(&mut decoded).unwrap();
    assert_eq!(decoded, expected());
    let report = image.verify().unwrap();
    assert!(report.md5_verified);
    assert!(!report.sha1_verified);
    assert_eq!(hex(&report.md5), "196066add11fb71c4c49cf1bb50d6d24");
    assert_eq!(
        hex(&report.sha1),
        "4766c63c7acd5175015e3e8b90013a827e63f4ee"
    );
    assert_eq!(report.bytes_read, image.len());
    assert_eq!(image.stream_position().unwrap(), image.len());
}

#[test]
fn uncompressed_segmented_image_matches_every_raw_byte() {
    let mut image = EwfImage::open(fixture("ext2.split.E01")).unwrap();
    assert_eq!(image.segment_paths().len(), 2);
    let mut decoded = Vec::new();
    image.read_to_end(&mut decoded).unwrap();
    assert_eq!(decoded, expected());
    assert!(image.verify().unwrap().md5_verified);
    assert!(
        image
            .sections()
            .iter()
            .any(|s| s.segment == 2 && s.kind == "data")
    );
}

#[test]
fn explicit_segments_are_sorted_by_header_not_filename() {
    let dir = tempfile::tempdir().unwrap();
    let first = dir.path().join("z-last-name.data");
    let second = dir.path().join("a-first-name.data");
    fs::copy(fixture("ext2.split.E01"), &first).unwrap();
    fs::copy(fixture("ext2.split.E02"), &second).unwrap();
    let mut image = EwfImage::open_segments([&second, &first]).unwrap();
    assert!(image.verify().unwrap().md5_verified);
}

#[test]
fn random_reads_cover_chunk_segment_and_eof_boundaries() {
    let expected = expected();
    for name in ["ext2.E01", "ext2.split.E01"] {
        let mut image = EwfImage::open(fixture(name)).unwrap();
        image.seek(SeekFrom::Start(123)).unwrap();
        for offset in [
            0,
            1,
            511,
            512,
            32767,
            32768,
            95 * 32768 - 19,
            95 * 32768,
            4_194_300,
            4_194_304,
            u64::MAX,
        ] {
            let mut data = [0xcc; 1000];
            let count = image.read_at(offset, &mut data).unwrap();
            let start = usize::try_from(offset.min(expected.len() as u64)).unwrap();
            let end = (start + 1000).min(expected.len());
            assert_eq!(
                &data[..count],
                &expected[start..end],
                "{name} offset {offset}"
            );
            assert!(data[count..].iter().all(|&b| b == 0xcc));
        }
        // Deterministic random offsets, varying buffers and cross-chunk reads.
        let mut seed = 0x1057_afe5_u64;
        for _ in 0..300 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
            let offset = seed % (image.len() + 1);
            let mut data = vec![0; (seed >> 32) as usize % 70000];
            let count = image.read_at(offset, &mut data).unwrap();
            assert_eq!(
                &data[..count],
                &expected[offset as usize..offset as usize + count]
            );
        }
        assert_eq!(image.stream_position().unwrap(), 123);
        image.verify().unwrap();
        assert_eq!(image.stream_position().unwrap(), 123);
    }
}

#[test]
fn seek_contract_and_empty_reads() {
    let mut image = EwfImage::open(fixture("ext2.E01")).unwrap();
    assert!(image.seek(SeekFrom::Current(-1)).is_err());
    assert_eq!(image.stream_position().unwrap(), 0);
    assert_eq!(image.seek(SeekFrom::End(-4)).unwrap(), image.len() - 4);
    let mut bytes = [0; 9];
    assert_eq!(image.read(&mut bytes).unwrap(), 4);
    assert_eq!(image.read(&mut bytes).unwrap(), 0);
    assert_eq!(image.seek(SeekFrom::Start(u64::MAX)).unwrap(), u64::MAX);
    assert!(image.seek(SeekFrom::Current(1)).is_err());
    assert_eq!(image.read(&mut bytes).unwrap(), 0);
    assert_eq!(image.read(&mut []).unwrap(), 0);
    assert_eq!(image.read_at(0, &mut []).unwrap(), 0);
}

#[test]
fn missing_duplicate_and_extra_segments_are_rejected() {
    let temp = tempfile::tempdir().unwrap();
    let first = temp.path().join("missing.E01");
    fs::copy(fixture("ext2.split.E01"), &first).unwrap();
    assert!(matches!(
        EwfImage::open(&first),
        Err(inodex::Error::MissingSegment { number: 2, .. })
    ));
    assert!(EwfImage::open_segments([fixture("ext2.split.E02")]).is_err());
    assert!(
        EwfImage::open_segments([fixture("ext2.split.E01"), fixture("ext2.split.E01")]).is_err()
    );
    assert!(EwfImage::open_segments([fixture("ext2.E01"), fixture("ext2.split.E02")]).is_err());
    assert!(EwfImage::open_segments(Vec::<PathBuf>::new()).is_err());
}

#[test]
fn lowercase_segment_discovery() {
    let temp = tempfile::tempdir().unwrap();
    for extension in ["E01", "E02"] {
        fs::copy(
            fixture(&format!("ext2.split.{extension}")),
            temp.path()
                .join(format!("disk.{}", extension.to_lowercase())),
        )
        .unwrap();
    }
    let mut image = EwfImage::open(temp.path().join("disk.e01")).unwrap();
    assert!(image.verify().unwrap().md5_verified);
}

fn check_libewf_fixture(name: &str) {
    let mut expected = Vec::new();
    flate2::read::GzDecoder::new(&include_bytes!("fixtures/libewf.raw.gz")[..])
        .read_to_end(&mut expected)
        .unwrap();
    let mut image = EwfImage::open(fixture(name)).unwrap();
    assert_eq!(image.len(), 131584);
    assert_eq!(image.metadata().chunk_count, 5);
    let mut decoded = Vec::new();
    image.read_to_end(&mut decoded).unwrap();
    assert_eq!(decoded, expected);
    let report = image.verify().unwrap();
    assert!(report.md5_verified);
    assert_eq!(hex(&report.md5), "1cccd033947fea762cc4b98b4e48b744");
    if name.contains("encase6") {
        assert!(report.sha1_verified);
    }
    let mut tail = [0; 1024];
    let count = image.read_at(image.len() - 1000, &mut tail).unwrap();
    assert_eq!(count, 1000);
    assert_eq!(&tail[..count], &expected[expected.len() - count..]);
}

macro_rules! corpus_test {
    ($test:ident, $fixture:literal) => {
        #[test]
        fn $test() {
            check_libewf_fixture($fixture);
        }
    };
}

corpus_test!(encase1_uncompressed_inline, "libewf-encase1-c0.E01");
corpus_test!(encase1_compressed_inline, "libewf-encase1-c2.E01");
corpus_test!(encase2_uncompressed, "libewf-encase2-c0.E01");
corpus_test!(encase2_compressed, "libewf-encase2-c2.E01");
corpus_test!(encase3_uncompressed, "libewf-encase3-c0.E01");
corpus_test!(encase3_compressed, "libewf-encase3-c2.E01");
corpus_test!(encase4_uncompressed, "libewf-encase4-c0.E01");
corpus_test!(encase4_compressed, "libewf-encase4-c2.E01");
corpus_test!(encase5_uncompressed, "libewf-encase5-c0.E01");
corpus_test!(encase5_compressed, "libewf-encase5-c2.E01");
corpus_test!(encase6_uncompressed, "libewf-encase6-c0.E01");
corpus_test!(encase6_compressed, "libewf-encase6-c2.E01");
corpus_test!(ftk_uncompressed, "libewf-ftk-c0.E01");
corpus_test!(ftk_compressed, "libewf-ftk-c2.E01");
